study_app::Application app(initial_round);
study_menu::Preferences preferences;
auto menu_focus = study_menu::Focus::start;

while (!platform_should_close()) {
    // 입력을 읽고 preferences와 menu_focus를 갱신한다.
    // 화면이나 라운드가 바뀌어도 preferences 객체는 유지된다.
}

inline Checkbox checkbox(Rect bounds, const Input& input, bool checked,
                         bool enabled = true) noexcept {
    Checkbox box;
    box.checked = checked;
    box.interaction = button(bounds, input, enabled);
    box.toggle_requested = box.interaction.activated;
    return box;
}

case Action::previous_badge:
    if (badge_ == 0) return false;
    --badge_;
    return true;
case Action::next_badge:
    if (badge_ >= badge_count - 1) return false;
    ++badge_;
    return true;

if (count == 0 || index >= count) return {};
// 사각형과 두 화살표의 배치 검증 뒤
s.previous_enabled = enabled && index > 0;
s.next_enabled = enabled && index < count - 1;
s.previous = button(left, input, s.previous_enabled);
s.next = button(right, input, s.next_enabled);
if (s.previous.activated) s.direction = -1;
else if (s.next.activated) s.direction = 1;

const auto intent = study_menu::evaluate(preferences, menu_focus, pointer, keys);
menu_focus = intent.focus;
(void)preferences.apply(intent.action);
confirm = intent.action == study_menu::Action::start;

if (!input.cancelled && input.press &&
    study_ui::contains(badge_bounds, *input.press)) {
    const auto s = study_ui::selector(badge_bounds, input,
        prefs.badge(), Preferences::badge_count);
    const auto action = s.direction < 0 ? Action::previous_badge
                      : s.direction > 0 ? Action::next_badge : Action::none;
    return Intent{Focus::badge, action};
}

if (app.screen() != shown_screen) {
    shown_screen = app.screen();
    if (shown_screen == study_app::Screen::menu)
        menu_focus = study_menu::Focus::start;
}

const auto icon = preferences.badge() == 0 ? base_icon : alternate_icon;
// 주 아이콘은 항상 그리고, 장식 두 개는 설정에 따라 그린다.
if (preferences.decorations()) {
    if (!images.draw(badge_quad, icon, crop) ||
        !images.draw(badge_quad, icon, translucent)) return 1;
}

if (plan->device_height != prepared_height) {
    ui_labels.reset();
    gpu_cache.clear();
    font.clear();
    if (!atlas.clear() || !ui_labels.init(font, gpu_cache, density)) return 1;
    prepared_height = plan->device_height;
}

study_menu::Preferences p;
const auto intent = study_menu::evaluate(p, study_menu::Focus::start,
    press_on_checkbox, {});
CHECK(p.decorations());       // 평가만으로는 변경되지 않는다.
CHECK(p.apply(intent.action));
CHECK(!p.decorations());
CHECK(p.apply(intent.action));
CHECK(p.decorations());       // 중복 적용하면 원래 값으로 돌아온다.
